:root{--ink:#11131a;--paper:#f2efe7;--gold:#d9a73b;--red:#b33a36;--muted:#77756f}*{box-sizing:border-box}body{margin:0;background:#151820;color:var(--ink);font-family:Arial,Helvetica,sans-serif}.shell{width:min(1180px,calc(100vw - 40px));min-height:720px;margin:20px auto;background:var(--paper);box-shadow:0 24px 70px #0008;overflow:hidden}header{height:78px;border-bottom:1px solid #d7d2c5;display:flex;align-items:center;justify-content:space-between;padding:0 38px}.brand{display:flex;align-items:center;gap:12px}.mark{width:40px;height:40px;border:2px solid var(--ink);display:grid;place-items:center;font-family:Georgia;font-weight:900}.brand small,.brand strong{display:block}.brand small{font-size:9px;letter-spacing:.25em;color:var(--muted)}.brand strong{font-family:Georgia;font-size:16px}.icon-btn{border:1px solid #bbb5a7;background:transparent;width:38px;height:38px;border-radius:50%;cursor:pointer}.screen{display:none}.screen.active{display:flex}.setup-copy{flex:1;padding:64px 55px}.eyebrow{font-size:11px;font-weight:bold;letter-spacing:.24em;color:#77736a}.setup-copy h1{font-family:Georgia,serif;font-size:82px;line-height:.82;margin:22px 0 28px;letter-spacing:-5px}.setup-copy h1 em{color:var(--red);font-weight:400}.setup-copy>p:not(.eyebrow){max-width:430px;color:#67655f}.fighters{display:flex;gap:8px;margin:32px 0}.fighter-chip{width:76px;height:94px;border:1px solid #cfcab9;background:#e8e4d7;cursor:pointer;position:relative;padding:6px}.fighter-chip.active{border:2px solid var(--red);background:#ddd5c3}.fighter-chip i{display:block;height:58px;border-radius:42px 42px 12px 12px;background:var(--chip);position:relative}.fighter-chip i:after{content:'';position:absolute;width:20px;height:24px;border-radius:50%;background:#222;left:50%;top:10px;transform:translateX(-50%)}.fighter-chip b{display:block;font-size:9px;text-align:center;margin-top:9px}.primary{border:0;background:var(--ink);color:white;height:54px;padding:0 20px;font-weight:bold;font-size:11px;letter-spacing:.12em;cursor:pointer}.primary span{float:right;margin-left:55px;color:var(--gold);font-size:18px}.hero-card{width:46%;min-height:642px;background:#1a1d24;position:relative;overflow:hidden}.hero-card:before{content:'';position:absolute;width:520px;height:520px;border:1px solid #393c44;border-radius:50%;left:50%;top:50%;transform:translate(-50%,-50%)}.ring{position:absolute;inset:0;display:flex;align-items:center;justify-content:center}.fighter-silhouette{width:260px;height:470px;position:relative}.fighter-silhouette:before{content:'';position:absolute;width:110px;height:130px;border-radius:48% 48% 35% 35%;background:var(--hero);left:75px;top:20px;box-shadow:0 25px 0 -12px var(--hero)}.fighter-silhouette:after{content:'';position:absolute;width:210px;height:270px;background:var(--hero);clip-path:polygon(28% 0,72% 0,100% 34%,78% 100%,22% 100%,0 34%);left:25px;top:145px}.selected-tag{position:absolute;bottom:36px;left:38px;color:white;border-left:3px solid var(--gold);padding-left:12px}.selected-tag span{display:block;font-size:8px;letter-spacing:.25em;color:#aaa}.selected-tag strong{font-family:Georgia;font-size:24px}
#bracket{padding:48px 55px;flex-direction:column}.topline{display:flex;justify-content:space-between;align-items:end}.topline h2{font-family:Georgia;font-size:38px;margin:8px 0}.rounds{display:flex;gap:8px}.round-dot{width:74px;height:5px;background:#d2cdbf}.round-dot.done{background:var(--red)}.round-dot.current{background:var(--gold)}.bracket-grid{height:510px;margin-top:30px;display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.round-col{display:flex;flex-direction:column;justify-content:space-around}.round-col h3{font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:#888}.match{height:70px;background:#e8e4d8;border:1px solid #d1ccbe;box-shadow:0 5px 12px #00000008}.match.active{border:2px solid var(--gold)}.slot{height:34px;padding:8px 10px;font-size:11px;font-weight:bold;display:flex;justify-content;align-items:center}.slot+.slot{border-top:1px solid #d1ccbe}.slot i{width:7px;height:7px;border-radius:50%;background:#777;display:inline-block;margin-right:8px}.slot.winner{background:#dcd4c0}.slot.loser{text-decoration:line-through;opacity:.5}.slot .score{margin-left:auto}.match.final-match{height:86px}.match.final-match .slot{height:42px}
#fight{flex-direction:column}.fight-head{height:78px;display:grid;grid-template-columns:1fr 150px 1fr;align-items:center;padding:0 38px}.fighter-name strong{display:block;font-family:Georgia;font-size:24px}.fighter-name span{font-size:9px;color:#777;letter-spacing:.18em}.fighter-name.right{text-align:right}.round-label{text-align:center}.round-label span{display:block;font-size:9px;letter-spacing:.2em}.round-label b{font-family:Georgia;font-size:28px}.health-row{height:16px;padding:0 38px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.health{background:#ccc5b5;height:10px}.health i{display:block;height:100%;width:100%;background:var(--red);transition:width .25s}.right-health i{float:right}.arena{height:470px;margin:10px 38px 0;position:relative;overflow:hidden;background:linear-gradient(#262934 0 60%,#171922 60%)}.crowd{position:absolute;inset:0;background:radial-gradient(circle at 10px 10px,#d7b976 0 2px,transparent 3px) 0 0/24px 24px;opacity:.15;mask:linear-gradient(#000 0 72%,transparent 72%)}.arena:after{content:'';position:absolute;left:-5%;bottom:-45px;width:110%;height:120px;background:#0d0e13;transform:perspective(300px) rotateX(20deg)}.spot{position:absolute;top:-30px;width:110px;height:300px;background:linear-gradient(#fff2,transparent);clip-path:polygon(42% 0,58% 0,100% 100%,0 100%);opacity:.55}.spot-a{left:15%}.spot-b{right:15%}.combatant{position:absolute;z-index:3;bottom:72px;width:150px;height:310px}.player{left:22%}.enemy{right:22%;transform:scaleX(-1)}.combatant .body{position:absolute;width:112px;height:190px;left:19px;top:58px;background:var(--pColor,#8c9ea2);clip-path:polygon(30% 0,70% 0,92% 28%,78% 100%,22% 100%,8% 28%);border-radius:50px 50px 20px 20px}.enemy .body{background:var(--eColor,#9b5a50)}.body i{position:absolute;width:56px;height:62px;border-radius:50%;background:#d09a72;left:28px;top:-36px}.enemy .body i{background:#9b8065}.glove{position:absolute;width:58px;height:58px;border-radius:50%;background:#b8a480;top:92px;z-index:4}.glove-l{left:-20px}.glove-r{right:-20px}.enemy .glove{background:#713a35}.legs{position:absolute;width:90px;height:100px;left:30px;bottom:-55px;border-left:24px solid #25272e;border-right:24px solid #25272e}.combatant.hit{animation:hit .25s}.player.attack{animation:punch .22s}.enemy.attack{animation:punch .22s}.impact{position:absolute;z-index:8;left:50%;top:32%;transform:translate(-50%) rotate(-4deg);font-family:Georgia;font-size:42px;font-weight:bold;color:var(--gold);text-shadow:2px 3px #111;opacity:0}.impact.show{animation:impact .7s}@keyframes punch{50%{transform:translateX(55px)}}@keyframes hit{30%{filter:brightness(2);transform:translateX(-20px)}}@keyframes impact{0%{opacity:0;scale:.5}20%{opacity:1;scale:1.2}100%{opacity:0;scale:1.2}}.controls{height:90px;display:flex;justify-content:center;gap:12px;align-items:center}.move{width:180px;height:58px;border:1px solid #bbb4a4;background:#ebe7dc;display:flex;align-items:center;text-align:left;cursor:pointer}.move:hover{border-color:var(--gold);transform:translateY(-2px)}.move kbd{width:38px;height:38px;margin:9px;border:1px solid #aaa;background:#ddd8ca;display:grid;place-items:center;font-family:Georgia}.move span{display:flex;flex-direction:column}.move strong{font-size:11px}.move small{font-size:8px;color:#777;margin-top:4px}
#result{height:642px;flex-direction:column;align-items:center;justify-content:center;text-align:center;background:radial-gradient(circle,#fff 0,#ede8dc 55%,#ded7c7 100%)}.trophy{font-size:86px;color:var(--gold);text-shadow:0 5px #8a651e}.result h1{}#result h1{font-family:Georgia;font-size:76px;margin:12px}.result-stats{display:flex;gap:1px;margin:20px 0 28px}.result-stats div{width:110px;height:70px;border:1px solid #ccc4b2;display:flex;flex-direction:column;justify-content:center}.result-stats strong{font-family:Georgia;font-size:28px}.result-stats span{font-size:8px;letter-spacing:.18em}.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%) translateY(100px);background:#111;color:white;padding:12px 18px;font-size:12px;transition:.3s}.toast.show{transform:translateX(-50%) translateY(0)}
@media(max-width:760px){.shell{width:100%;margin:0;min-height:100vh}header{padding:0 16px}.hero-card{display:none}.setup-copy{padding:45px 22px}.setup-copy h1{font-size:58px}.fighters{flex-wrap:wrap}.fighter-chip{width:68px}.bracket-grid{grid-template-columns:repeat(2,1fr);height:auto}.round-col:nth-child(n+3){display:none}#bracket{padding:30px 20px}.arena{margin:10px 10px 0;height:430px}.combatant{transform:scale(.75)}.player{left:8%}.enemy{right:8%}.enemy{transform:scaleX(-1) scale(.75)}.fight-head{padding:0 12px}.health-row{padding:0 12px}.controls{gap:5px}.move{width:31%;height:64px}.move kbd{display:none}.move span{margin:auto}.move small{display:none}}

const fighters=[
 {name:'Atlas',color:'#71848a',style:'Balanced',power:12},
 {name:'Viper',color:'#8a594f',style:'Fast',power:10},
 {name:'Titan',color:'#74715f',style:'Heavy',power:15},
 {name:'Knox',color:'#947b62',style:'Counter',power:11},
 {name:'Reign',color:'#665a78',style:'Technical',power:12},
 {name:'Ghost',color:'#5f7272',style:'Elusive',power:9},
 {name:'Rex',color:'#9a7957',style:'Brawler',power:14},
 {name:'Blaze',color:'#b06a45',style:'Aggressive',power:13}
];
let selected=0, bracket=[], round=0, fightIndex=0, pHP=100,eHP=100, playerWins=0, kos=0, locked=false, timer=30, timerID;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function show(id){ $$('.screen').forEach(x=>x.classList.remove('active')); $(id).classList.add('active') }
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),1500)}
function init(){
 $('#fighters').innerHTML=fighters.map((f,i)=>`<button class="fighter-chip ${i===selected?'active':''}" data-i="${i}" style="--chip:${f.color}"><i></i><b>${f.name}</b></button>`).join('');
 $$('.fighter-chip').forEach(b=>b.onclick=()=>{selected=+b.dataset.i;$$('.fighter-chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');updateHero()});
 updateHero();
}
function updateHero(){const f=fighters[selected];$('#selectedName').textContent=f.name;$('#heroSilhouette').style.setProperty('--hero',f.color)}
$('#startBtn').onclick=()=>{startTournament();show('#bracket')};
function startTournament(){round=0;fightIndex=0;playerWins=0;kos=0;bracket=[[...fighters.map((_,i)=>i)]];renderBracket();nextMatch()}
function names(ids){return ids.map(i=>fighters[i].name)}
function roundName(r){return ['QUARTER FINALS','SEMI FINALS','FINAL'][r]||'FINAL'}
function renderBracket(){
 $('#roundTitle').textContent=roundName(round);
 $('#roundDots').innerHTML=['Quarter','Semi','Final'].map((n,i)=>`<div class="round-dot ${i<round?'done':i===round?'current':''}"></div>`).join('');
 const rounds=[bracket[0],bracket[0]?.length?chunk(bracket[0],2).map(p=>p[0]):[],[],[]];
 // Display actual tournament progress: fixed 4-round columns where spaces are seeded matches
 const cols=[];
 cols[0]=chunk(bracket[0],2);
 cols[1]=(bracket[1]||[null,null,null,null]).length?[bracket[1]]:[[]];
 cols[2]=(bracket[2]||[]).length?[bracket[2]]:[[]];
 cols[3]=(bracket[3]||[]).length?[bracket[3]]:[[]];
 $('#bracketGrid').innerHTML=['QUARTER','SEMI','FINAL','CHAMPION'].map((title,c)=>{
   let col=[];
   if(c===0) col=chunk(bracket[0],2).map((m,i)=>({m,active:i===fightIndex&&round===0}));
   if(c===1) col=[0,1].map(i=>({m:bracket[1]?.slice(i*2,i*2+2)||[null,null],active:false}));
   if(c===2) col=[{m:bracket[2]||[null,null],active:false}];
   if(c===3) col=[{m:[bracket[3]?.[0]??null,null],active:false}];
   return `<div class="round-col"><h3>${title}</h3>${col.map(({m,active})=>`<div class="match ${active?'active':''} ${c===2?'final-match':''}">${m.map((id,j)=>`<div class="slot ${id!=null&&bracket[c+1]?.includes(id)?'winner':''}"><i></i>${id!=null?fighters[id].name:'TBD'}${j===0?'': ''}</div>`).join('')}</div>`).join('')}</div>`
 }).join('');
}
function chunk(a,n){let out=[];for(let i=0;i<a.length;i+=n)out.push(a.slice(i,i+n));return out}
function nextMatch(){
 if(round===0){
   if(fightIndex>=4){advanceRound([advanceWinner(round,fightIndex-1)]);return}
   const pair=chunk(bracket[0],2)[fightIndex]; startVs(pair);
 }else if(round===1){
   if(!bracket[1]||bracket[1].length<4){/* filled when advancing */}
 }
}
let quarterWinners=[], semiWinners=[], userAlive=true;
function advanceRound(){ }
function startVs(pair){
 show('#bracket');renderBracket();
 setTimeout(()=>{
   const hasUser=pair.includes(selected);
   if(!hasUser){
     const winner=Math.random()<.5?pair[0]:pair[1];
     quarterWinners[ fightIndex ]=winner;
     toast(`${fighters[pair[0]].name} defeated ${fighters[pair[1]].name}`);
     fightIndex++; if(fightIndex===4){round=1;bracket[1]=quarterWinners.slice();renderBracket();setTimeout(()=>runSemis(),900)}else setTimeout(()=>nextMatch(),900);
   }else{
     const enemy=pair.find(i=>i!==selected); startFight(selected,enemy);
   }
 },700);
}
function runSemis(){
 if(!semiWinners.length){semiWinners=[]}
 const pair=[quarterWinners[0],quarterWinners[1]];
 if(pair.includes(selected)){startVsSemi(pair)}else{const w=Math.random()<.5?pair[0]:pair[1];semiWinners.push(w);runSemisNext()}
}
function runSemisNext(){
 if(semiWinners.length===1){
   const pair=[quarterWinners[2],quarterWinners[3]]; if(pair.includes(selected))startVsSemi(pair);else{semiWinners.push(Math.random()<.5?pair[0]:pair[1]);runFinal()}
 }else runFinal()
}
function startVsSemi(pair){round=1;fightIndex=0;bracket[1]=pair.concat(semiWinners.filter(x=>pair.indexOf(x)<0));renderBracket();startFight(selected,pair.find(i=>i!==selected),true)}
function runFinal(){round=2;if(semiWinners.includes(selected)){bracket[2]=semiWinners.slice();renderBracket();setTimeout(()=>startFight(selected,semiWinners.find(i=>i!==selected)),700)}else{renderBracket();setTimeout(()=>finish(false),700)}}
function startFight(p,e,semi=false){show('#fight');pHP=eHP=100;locked=false;timer=30;$('#pName').textContent=fighters[p].name;$('#eName').textContent=fighters[e].name;$('#pHealth').style.width='100%';$('#eHealth').style.width='100%';$('#player').style.setProperty('--pColor',fighters[p].color);$('#enemy').style.setProperty('--eColor',fighters[e].color);clearInterval(timerID);timerID=setInterval(()=>{timer--;$('#timer').textContent=timer;if(timer<=0){clearInterval(timerID);resolveFight(pHP>=eHP)}},1000);updateRoundLabel(semi)}
function updateRoundLabel(semi){$('#fightRound').textContent=round===0?'QUARTER FINAL':round===1?'SEMI FINAL':'FINAL'}
function resolveFight(win){clearInterval(timerID);locked=true;if(win){toast('VICTORY');playerWins++;setTimeout(()=>afterUserWin(),900)}else{toast('KNOCKOUT DEFEAT');setTimeout(()=>finish(false),900)}}
function afterUserWin(){quarterWinners=quarterWinners.filter(Boolean);if(round===0){quarterWinners.push(selected);fightIndex++;if(fightIndex===4){round=1;bracket[1]=quarterWinners.slice();renderBracket();show('#bracket');setTimeout(runSemisForReal,900)}else nextMatch()}else if(round===1){round=2;bracket[2]=[selected];renderBracket();show('#bracket');setTimeout(runFinalForReal,900)}else finish(true)}
function runSemisForReal(){const p=quarterWinners.filter(x=>x!==selected).slice(0,1)[0];const pair=[selected,p]; // first semi with user guaranteed? bracket logic
 startFight(selected,p,true)}
function runFinalForReal(){const opponent= fighters.map((_,i)=>i).find(i=>i!==selected && bracket[1].includes(i));startFight(selected,opponent||semiWinners.find(i=>i!==selected)||1)}
$$('.move').forEach(b=>b.onclick=()=>{if(!locked)playMove(b.dataset.move)});
window.addEventListener('keydown',e=>{if(e.key==='1')playMove('jab');if(e.key==='2')playMove('cross');if(e.key==='3')playMove('block')});
function playMove(move){
 locked=true;const pf=fighters[selected],enemyId= fighters.findIndex(f=>f.name===$('#eName').textContent),ef=fighters[enemyId];
 const player=$('#player'),enemy=$('#enemy'),impact=$('#impact');
 if(move==='block'){pHP=Math.min(100,pHP+4);enemyId;$('#pHealth').style.width=pHP+'%';toast('GUARD');setTimeout(()=>locked=false,600);return}
 let dmg=(move==='jab'?7:13)+Math.floor(pf.power/5)+Math.floor(Math.random()*5);
 player.classList.add('attack');enemy.classList.add('hit');impact.textContent=['NICE!','SOLID!','PERFECT!'][Math.floor(Math.random()*3)];impact.classList.add('show');
 eHP=Math.max(0,eHP-dmg);$('#eHealth').style.width=eHP+'%';setTimeout(()=>{player.classList.remove('attack');enemy.classList.remove('hit');impact.classList.remove('show')},260);
 if(eHP<=0){kos++;resolveFight(true);return}
 setTimeout(()=>{if(!locked)return;let edmg=move==='block'?0:(Math.floor(Math.random()*10)+ef.power/2)|0;if(edmg){enemy.classList.add('attack');player.classList.add('hit');pHP=Math.max(0,pHP-edmg);$('#pHealth').style.width=pHP+'%';setTimeout(()=>{enemy.classList.remove('attack');player.classList.remove('hit')},260)}if(pHP<=0)resolveFight(false);else locked=false},650);
}
function finish(win){clearInterval(timerID);show('#result');$('#resultEyebrow').textContent=win?'KINGS CUP · CHAMPION':'TOURNAMENT OVER';$('#resultTitle').textContent=win?'CHAMPION!':'DEFEATED';$('#resultText').textContent=win?'Undefeated in the ring. Your name is legend.':'The crown slips away. Return stronger.';$('#winsStat').textContent=playerWins;$('#koStat').textContent=kos}
$('#againBtn').onclick=()=>{show('#setup')};$('#soundBtn').onclick=()=>toast($('#soundBtn').textContent==='♪'?'Sound on':'Sound off');
init();

